function polar2cartesian(cx, cy, r, a) {
    return {
        x: cx + r * Math.cos(a),
        y: cy + r * Math.sin(a)
    };
}

function sdCircle(x, y, cx, cy, r) {
  return Math.sqrt((x - cx) * (x - cx) + (y - cy) * (y - cy)) - r;
}

function sdTriangle(x, y, cx, cy, r, a) {
    // Define the triangle vertices using polar coordinates
    let A = polar2cartesian(cx, cy, r, a);
    let B = polar2cartesian(cx, cy, r, a + TAU / 3);
    let C = polar2cartesian(cx, cy, r, a + 2 * TAU / 3);

    // Function to compute edge distance
    function edgeDistance(px, py, ex, ey, fx, fy) {
        let vx = px - ex, vy = py - ey;
        let ux = fx - ex, uy = fy - ey;
        let t = Math.max(0, Math.min(1, (vx * ux + vy * uy) / (ux * ux + uy * uy)));
        let dx = vx - t * ux, dy = vy - t * uy;
        return Math.sqrt(dx * dx + dy * dy);
    }

    // Compute distances to edges
    let d1 = edgeDistance(x, y, A.x, A.y, B.x, B.y);
    let d2 = edgeDistance(x, y, B.x, B.y, C.x, C.y);
    let d3 = edgeDistance(x, y, C.x, C.y, A.x, A.y);

    // Check if point is inside the triangle
    let s1 = (B.x - A.x) * (y - A.y) - (B.y - A.y) * (x - A.x) < 0 ? -1 : 1;
    let s2 = (C.x - B.x) * (y - B.y) - (C.y - B.y) * (x - B.x) < 0 ? -1 : 1;
    let s3 = (A.x - C.x) * (y - C.y) - (A.y - C.y) * (x - C.x) < 0 ? -1 : 1;

    let inside = s1 === s2 && s2 === s3;
    return inside ? -Math.min(d1, d2, d3) : Math.min(d1, d2, d3);
}

function sdBox(x, y, cx, cy, r, a) {
    // Define the box vertices using polar coordinates
    var A = polar2cartesian(cx, cy, r, a);
    var B = polar2cartesian(cx, cy, r, a + TAU / 4);
    var C = polar2cartesian(cx, cy, r, a + TAU / 2);
    let D = polar2cartesian(cx, cy, r, a + 3 * TAU / 4);

    // Function to compute edge distance
    function edgeDistance(px, py, ex, ey, fx, fy) {
        var vx = px - ex, vy = py - ey;
        var ux = fx - ex, uy = fy - ey;
        var t = Math.max(0, Math.min(1, (vx * ux + vy * uy) / (ux * ux + uy * uy)));
        var dx = vx - t * ux, dy = vy - t * uy;
        return Math.sqrt(dx * dx + dy * dy);
    }

    // Compute distances to edges
    var d1 = edgeDistance(x, y, A.x, A.y, B.x, B.y);
    var d2 = edgeDistance(x, y, B.x, B.y, C.x, C.y);
    var d3 = edgeDistance(x, y, C.x, C.y, D.x, D.y);
    let d4 = edgeDistance(x, y, D.x, D.y, A.x, A.y);

    // Check if point is inside the box
    var s1 = (B.x - A.x) * (y - A.y) - (B.y - A.y) * (x - A.x) < 0 ? -1 : 1;
    var s2 = (C.x - B.x) * (y - B.y) - (C.y - B.y) * (x - B.x) < 0 ? -1 : 1;
    var s3 = (D.x - C.x) * (y - C.y) - (D.y - C.y) * (x - C.x) < 0 ? -1 : 1;
    let s4 = (A.x - D.x) * (y - D.y) - (A.y - D.y) * (x - D.x) < 0 ? -1 : 1;

    var inside = s1 === s2 && s2 === s3 && s3 === s4;
    return inside ? -Math.min(d1, d2, d3, d4) : Math.min(d1, d2, d3, d4);
}
function sdPolygon(x, y, cx, cy, r, a, n) {
    let vertices = [];
    for (let i = 0; i < n; i++) {
        vertices.push(polar2cartesian(cx, cy, r, a + (i * TAU / n)));
    }

    function edgeDistance(px, py, ex, ey, fx, fy) {
        var vx = px - ex, vy = py - ey;
        var ux = fx - ex, uy = fy - ey;
        var t = Math.max(0, Math.min(1, (vx * ux + vy * uy) / (ux * ux + uy * uy)));
        var dx = vx - t * ux, dy = vy - t * uy;
        return Math.sqrt(dx * dx + dy * dy);
    }

    let distances = [];
    for (let i = 0; i < n; i++) {
        let nextIndex = (i + 1) % n;
        distances.push(edgeDistance(x, y, vertices[i].x, vertices[i].y, vertices[nextIndex].x, vertices[nextIndex].y));
    }

    let signs = [];
    for (let i = 0; i < n; i++) {
        var nextIndex = (i + 1) % n;
        signs.push((vertices[nextIndex].x - vertices[i].x) * (y - vertices[i].y) - (vertices[nextIndex].y - vertices[i].y) * (x - vertices[i].x) < 0 ? -1 : 1);
    }

    var inside = signs.every(sign => sign === signs[0]);
    return inside ? -Math.min(...distances) : Math.min(...distances);
}

function sdStar(x, y, cx, cy, r, n, m) {
    // Shift coordinates to be relative to the center
    var dx = x - cx;
    let dy = y - cy;

    // Precompute shape constants
    let an = Math.PI / n;
    let en = Math.PI / m;  // m should be between 2 and n
    let acs = { x: Math.cos(an), y: Math.sin(an) };
    let ecs = { x: Math.cos(en), y: Math.sin(en) }; // ecs = {x: 0, y: 1} for a regular polygon

    // Compute radial position
    let angle = Math.atan2(dy, dx);
    let bn = ((angle % (2 * an)) + (2 * an)) % (2 * an) - an;
    let len = Math.sqrt(dx * dx + dy * dy);
    let p = { x: len * Math.cos(bn), y: Math.abs(len * Math.sin(bn)) };

    // Apply transformations
    p.x -= r * acs.x;
    p.y -= r * acs.y;
    let dotProduct = p.x * ecs.x + p.y * ecs.y;
    let clampedDot = Math.max(0, Math.min(-dotProduct, r * acs.y / ecs.y));
    p.x += ecs.x * clampedDot;
    p.y += ecs.y * clampedDot;

    return Math.sqrt(p.x * p.x + p.y * p.y) * Math.sign(p.x);
}

