const FPS = 10;
const SCL = 3;
const NUM = 3;
const PAD = 6;
let HGHT;

const PENS = ["red", "green", "blue"]
let svgGrps;

function setup() {
  createCanvas(210 * SCL, 297 * SCL);
	HGHT = (height - (NUM - 1) * PAD * SCL)/ NUM;
  frameRate(FPS);
  strokeWeight(1);
	noFill();
	// svg
	svgGrps = [];
}

function draw() {
  background("beige");
  var t = frameCount / FPS;

	for (let i = 0; i < PENS.length; i++) {
		svgGrps[i] = ``;
	}

	for (let i = 0; i < NUM; i++) {
		drawState({x: 0, y: i * HGHT + i * PAD * SCL, w: width, h: HGHT}, t+i*(TAU/NUM));
	}

	// // noLoop() removed for animation
}

function mousePressed() {
	if (mouseButton === RIGHT) return;
	if (isLooping()) {
    // noLoop() removed for animation
  } else {
    loop();
  }
}

function keyPressed() {
	if (key === "s") {
		saveSVG("epi_sdf_shapes.svg.txt");
	}
}

function drawState(dim, t) {
	const sdfCirc = (x, y, t) => sdCircle(x + sin(t) * dim.w/4, y, dim.x+dim.w/2, dim.y+dim.h/2, min(dim.w, dim.h) / 2.5);
	const sdfTria = (x, y, t) => sdTriangle(x -sin(t) * dim.w/4, y, dim.x+dim.w/2, dim.y+dim.h/2, min(dim.w, dim.h) / 2.25, t);
	const sdfBoxx = (x, y, t) => sdPolygon(x, y, dim.x+dim.w/2, dim.y+dim.h/2, min(dim.w, dim.h) / 2.1, -t, 4);
	showPattern(sdfCirc, dim, t, PAD*SCL, 1/6*PAD*SCL, 0 % PENS.length);
	showPattern(sdfTria, dim, t, PAD*SCL, 3/6*PAD*SCL, 1 % PENS.length);
	showPattern(sdfBoxx, dim, t, PAD*SCL, 5/6*PAD*SCL, 2 % PENS.length);
}

function showPattern(sdfFunc, dim, t, PAD, OFFY, clrIdx) {
	stroke(PENS[clrIdx % PENS.length]);
	for (let y = dim.y + OFFY; y < dim.y + dim.h; y += PAD) {
		let svgPts = "";
		beginShape();
		for (let x = dim.x; x < dim.x + dim.w; x += 2) {
			const noi = noise(x/321 + clrIdx, y/231 + clrIdx, frameCount/321);
			const dst = sdfFunc(x, y, t);
			const amp = noi * PAD * 0.75 *  (abs(dst) < SCL ? 0.65 : dst > 0 ? 0.2 : 1.4);
			const ang = x;
			const px = x;
			const py = y + sin(ang + frameCount) * amp;
			vertex(px, py);
			svgPts += `${nf(px, 0, 2)},${nf(py, 0, 2)} `;
		}
		endShape();
		svgGrps[clrIdx % PENS.length] += `<polyline points="${svgPts}" />\n`;
	}
}




function saveSVG(svg_name = "epi.svg.txt") {
	let svgStr = `<svg width="600" height="600" xmlns="http://www.w3.org/2000/svg">\n`;
	for (let i = 0; i < svgGrps.length; i++) {
		svgStr += `<g stroke="${PENS[i]}" id="${PENS[i]}">\n`;
		svgStr += svgGrps[i];
		svgStr += `</g>\n`;
	}
	svgStr += `</svg>`;

	// console.log(svgStr)
	save(svgStr.split("\n"), svg_name)
}
